begin;
set local lock_timeout='2s';set local statement_timeout='10s';set local search_path='';
select pg_catalog.pg_advisory_xact_lock(1261585232,1347374169);
do $financial_authority$ declare t record;b record;a record;v_before boolean:=true;v_after boolean:=true;v_hash text;
begin
 if current_user<>'postgres' then raise exception 'K2_PAYMENT_VERDICT_OWNER_REQUIRED';end if;
 for t in select * from jsonb_to_recordset('[{"identity":"public.is_admin()","body":"9be026764714651ede1a53fa53b7222b8c701bb5134c89a8183ca56d3c688f08","acl":null,"config":["search_path=public"],"definer":true},{"identity":"k2_private.verify_admin_bff_request(text, bigint, uuid, uuid, text, text)","body":"30ac692b79569f22b4e6084891a7c3b1f084d53816d0cbead8390d8a93651ea2","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"definer":true},{"identity":"k2_private.guard_order_delivery_charge_v1()","body":"8a3d22eb5ee128b8b491bc9e85ff33af98704eebfafdb40a70a1d797277430af","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"definer":true}]'::jsonb)
  as x(identity text,body text,acl text[],config text[],definer boolean) loop
  select * into b from pg_proc where oid=to_regprocedure(t.identity);
  if not found or pg_get_userbyid(b.proowner)<>'postgres' or b.proacl::text[] is distinct from t.acl
   or b.proconfig is distinct from t.config or b.prosecdef is distinct from t.definer
   or encode(extensions.digest(convert_to(replace(b.prosrc,chr(13)||chr(10),chr(10)),'UTF8'),'sha256'),'hex') is distinct from t.body
   then raise exception 'K2_PAYMENT_VERDICT_DEPENDENCY_DRIFT';end if;
 end loop;
 for t in select * from jsonb_to_recordset('[{"identity":"public.set_order_request_payment_status(uuid, text, text, jsonb)","before":"3c8e54cf176cd12427a3934a8bc489b98e97a43e95b4eab31698b1ee3addfdcd","after":"dbbcfc51ed09c8ce496b5de6af0dc469527b088b5f04e122e9973122ff4f1e53","body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_from text;\n  v_submitter uuid;\n  v_structured_evidence jsonb := ''{}''::jsonb;\n  v_method text;\n  v_amount numeric;\n  v_currency text;\n  v_payer_name text;\n  v_payment_reference text;\n  v_proof_asset_ref text;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() or auth.uid() is null\n     or coalesce(auth.jwt()->>''aal'','''') <> ''aal2'' then\n    raise exception using errcode=''42501'', message=''K2_ADMIN_AAL2_REQUIRED'';\n  end if;\n\n  if p_to_status in (''verified'',''failed'',''refunded'') and not coalesce(public.is_admin(),false) then\n    raise exception using errcode=''42501'',message=''K2_PAYMENT_VERDICT_ADMIN_REQUIRED'';\n  end if;\n  select * into v_order from public.order_requests where id=p_order_request_id for update;\n  if not found then raise exception using errcode=''23514'', message=''K2_PAYMENT_ORDER_INELIGIBLE''; end if;\n  v_from := v_order.payment_status;\n  if p_to_status = v_from then return v_order; end if;\n\n  if not coalesce((\n    (v_from=''not_requested'' and p_to_status=''awaiting_instructions'') or\n    (v_from=''awaiting_instructions'' and p_to_status in (''evidence_submitted'',''failed'')) or\n    (v_from=''evidence_submitted'' and p_to_status in (''verified'',''failed'')) or\n    (v_from=''failed'' and p_to_status=''evidence_submitted'') or\n    (v_from=''verified'' and p_to_status=''refunded'')\n  ), false) then\n    raise exception using errcode=''23514'', message=''K2_PAYMENT_TRANSITION_INVALID'';\n  end if;\n\n  if length(trim(coalesce(p_evidence_note,''''))) > 1000 or\n     (p_to_status not in (''awaiting_instructions'', ''evidence_submitted'') and nullif(trim(coalesce(p_evidence_note,'''')),'''') is null) then\n    raise exception using errcode=''23514'', message=''K2_PAYMENT_EVIDENCE_REQUIRED'';\n  end if;\n\n  -- Refund reconciliation remains available for a verified cancelled/fulfilled order;\n  -- all new attempts and collection/verification require an open order.\n  if p_to_status <> ''refunded'' and v_order.status not in (''submitted'',''confirmed'') then\n    raise exception using errcode=''23514'', message=''K2_PAYMENT_ORDER_INELIGIBLE'';\n  end if;\n\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  if p_to_status in (''evidence_submitted'',''verified'') then\n    -- K2_PAYMENT_BALANCE_INTEGRITY_V1\n    perform 1 from public.order_request_items where order_request_id=v_order.id order by id for update;\n    perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN''\n      and b.sku in (select sku from public.order_request_items where order_request_id=v_order.id)\n      order by b.sku for update;\n    perform 1 from public.inventory_reservations where order_request_id=v_order.id order by sku,batch_id,id for update;\n    perform 1 from public.product_batches b where b.id in (\n      select batch_id from public.inventory_reservations where order_request_id=v_order.id and status=''active''\n    ) order by b.sku,b.id for update;\n\n    if exists (\n      select 1 from public.order_request_items i\n      left join public.inventory_balances b on b.sku=i.sku and b.location_code=''MANILA_MAIN''\n      where i.order_request_id=v_order.id and (\n        b.sku is null or b.reserved is null or b.on_hand is null\n        or b.reserved<0 or b.reserved>b.on_hand\n        or b.reserved<(select coalesce(sum(r.quantity),0) from public.inventory_reservations r\n          where r.order_request_id=v_order.id and r.sku=i.sku and r.status=''active'')\n      )\n    ) then\n      raise exception using errcode=''23514'', message=''K2_PAYMENT_STOCK_INELIGIBLE'';\n    end if;\n\n    if not exists(select 1 from public.order_request_items where order_request_id=v_order.id)\n      or exists (\n        select 1 from public.inventory_reservations r\n        left join public.order_request_items i on i.id=r.order_request_item_id and i.order_request_id=v_order.id and i.sku=r.sku\n        left join public.product_batches b on b.id=r.batch_id and b.sku=r.sku\n        where r.order_request_id=v_order.id and r.status=''active''\n          and (i.id is null or b.id is null or r.quantity<=0\n            or ((r.committed_at is not null or r.committed_by is not null or r.commit_cause is not null)\n              and not coalesce(r.committed_at is not null and r.committed_by is not null\n                and r.commit_cause in (''confirmation'',''payment_verification''),false))\n            or (r.committed_at is null and (r.expires_at is null or r.expires_at<=v_k2_instant))\n            or b.reserved_quantity < (select sum(r2.quantity) from public.inventory_reservations r2 where r2.batch_id=b.id and r2.status=''active''))\n      )\n      or exists (\n        select 1 from public.order_request_items i where i.order_request_id=v_order.id\n        and i.quantity <> coalesce((\n          select sum(r.quantity) from public.inventory_reservations r\n          join public.product_batches b on b.id=r.batch_id and b.sku=r.sku\n          where r.order_request_id=v_order.id and r.order_request_item_id=i.id and r.sku=i.sku\n            and r.status=''active'' and r.quantity>0\n            and (r.committed_at is not null or r.expires_at>v_k2_instant)\n            and b.inventory_status=''available''\n            and b.quantity>=b.reserved_quantity and b.reserved_quantity>=r.quantity\n            and k2_private.lot_is_eligible_v1(b)\n        ),0)\n      ) then\n      raise exception using errcode=''23514'', message=''K2_PAYMENT_STOCK_INELIGIBLE'';\n    end if;\n  end if;\n\n  if p_to_status = ''evidence_submitted'' then\n    if p_payment_evidence is not null and p_payment_evidence <> ''{}''::jsonb then\n      v_method := p_payment_evidence->>''method'';\n      if v_method is null or v_method not in (''gcash'', ''bank_transfer'', ''maya'', ''cash'', ''other'') then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_METHOD_INVALID'';\n      end if;\n\n      begin\n        v_amount := (p_payment_evidence->>''amount'')::numeric;\n      exception when others then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_AMOUNT_INVALID'';\n      end;\n      if v_amount is null or v_amount <= 0 or v_amount > 10000000 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_AMOUNT_INVALID'';\n      end if;\n\n      v_currency := coalesce(p_payment_evidence->>''currency'', ''PHP'');\n      if v_currency <> ''PHP'' then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_CURRENCY_INVALID'';\n      end if;\n\n      v_payer_name := trim(coalesce(p_payment_evidence->>''payer_name'', ''''));\n      if length(v_payer_name) not between 1 and 140 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_PAYER_INVALID'';\n      end if;\n\n      v_payment_reference := trim(coalesce(p_payment_evidence->>''payment_reference'', ''''));\n      if length(v_payment_reference) not between 1 and 100 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_REFERENCE_INVALID'';\n      end if;\n\n      v_proof_asset_ref := trim(coalesce(p_payment_evidence->>''proof_asset_ref'', ''''));\n      if length(v_proof_asset_ref) > 500 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_PROOF_INVALID'';\n      end if;\n\n      v_structured_evidence := jsonb_build_object(\n        ''method'', v_method,\n        ''amount'', v_amount,\n        ''currency'', v_currency,\n        ''payer_name'', v_payer_name,\n        ''payment_reference'', v_payment_reference,\n        ''proof_asset_ref'', nullif(v_proof_asset_ref, ''''),\n        ''submitted_at'', v_k2_instant,\n        ''submitted_by'', auth.uid()\n      );\n    else\n      -- If structured fields omitted, note must be present\n      if nullif(trim(coalesce(p_evidence_note, '''')), '''') is null then\n        raise exception using errcode=''23514'', message=''K2_PAYMENT_EVIDENCE_REQUIRED'';\n      end if;\n      v_structured_evidence := jsonb_build_object(\n        ''legacy_note'', trim(p_evidence_note),\n        ''submitted_at'', v_k2_instant,\n        ''submitted_by'', auth.uid()\n      );\n    end if;\n\n    update public.order_requests\n    set payment_status = p_to_status,\n        payment_evidence = v_structured_evidence,\n        updated_at = v_k2_instant\n    where id = v_order.id\n    returning * into v_order;\n\n    insert into public.order_request_events(\n      order_request_id, from_status, to_status, reason, actor_id, metadata, created_at\n    )\n    values(\n      v_order.id, v_order.status, v_order.status, trim(coalesce(p_evidence_note, v_payment_reference, '''')),\n      auth.uid(),\n      jsonb_build_object(\n        ''event'', ''payment_status_changed'',\n        ''from'', v_from,\n        ''to'', p_to_status,\n        ''corrected_attempt'', v_from = ''failed'',\n        ''payment_evidence'', v_structured_evidence\n      ),\n      v_k2_instant\n    );\n\n  elsif p_to_status = ''verified'' then\n    select actor_id into v_submitter from public.order_request_events\n      where order_request_id = v_order.id and metadata->>''event'' = ''payment_status_changed''\n        and metadata->>''to'' = ''evidence_submitted''\n      order by created_at desc, id desc limit 1;\n\n    if v_submitter is null or v_submitter = auth.uid() then\n      raise exception using errcode=''42501'', message=''K2_PAYMENT_INDEPENDENT_REVIEW_REQUIRED'';\n    end if;\n\n    -- K2_STRUCTURED_PAYMENT_STOCK_COMMITMENT_V1: after eligibility and distinct review.\n    perform public.commit_order_request_stock_v1(v_order.id,''payment_verification'',p_evidence_note);\n    v_structured_evidence := coalesce(v_order.payment_evidence, ''{}''::jsonb) || jsonb_build_object(\n      ''verified_at'', v_k2_instant,\n      ''verified_by'', auth.uid(),\n      ''verification_note'', trim(p_evidence_note)\n    );\n\n    update public.order_requests\n    set payment_status = p_to_status,\n        payment_evidence = v_structured_evidence,\n        updated_at = v_k2_instant\n    where id = v_order.id\n    returning * into v_order;\n\n    insert into public.order_request_events(\n      order_request_id, from_status, to_status, reason, actor_id, metadata, created_at\n    )\n    values(\n      v_order.id, v_order.status, v_order.status, trim(p_evidence_note),\n      auth.uid(),\n      jsonb_build_object(\n        ''event'', ''payment_status_changed'',\n        ''from'', v_from,\n        ''to'', p_to_status,\n        ''corrected_attempt'', false,\n        ''verification'', jsonb_build_object(\n          ''verified_by'', auth.uid(),\n          ''verified_at'', v_k2_instant,\n          ''note'', trim(p_evidence_note)\n        )\n      ),\n      v_k2_instant\n    );\n\n  else\n    update public.order_requests\n    set payment_status = p_to_status,\n        updated_at = v_k2_instant\n    where id = v_order.id\n    returning * into v_order;\n\n    insert into public.order_request_events(\n      order_request_id, from_status, to_status, reason, actor_id, metadata, created_at\n    )\n    values(\n      v_order.id, v_order.status, v_order.status, trim(coalesce(p_evidence_note, '''')),\n      auth.uid(),\n      jsonb_build_object(\n        ''event'', ''payment_status_changed'',\n        ''from'', v_from,\n        ''to'', p_to_status,\n        ''corrected_attempt'', v_from = ''failed''\n      ),\n      v_k2_instant\n    );\n  end if;\n\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return v_order;\nend;\n","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"definer":true},{"identity":"public.execute_admin_fulfillment_command_v1(text, bigint, uuid, uuid, text, text)","before":"8653f7f59923f7469f2bb7e77cc5dd13b5535fb3e504023994cd4f8af8199606","after":"1bcff4e4a81b21e0b9768ca0d02e9e43e3d4546d2811f41f30d2935bbff523e3","body":"\ndeclare\n  v_actor uuid := auth.uid();\n  v_payload jsonb;\n  v_payload_hash text;\n  v_existing k2_private.admin_command_receipts;\n  v_order public.order_requests;\n  v_result jsonb;\n  v_uuid uuid;\n  v_count integer;\n  v_inserted integer;\n  v_limit integer;\nbegin\n  if not k2_private.verify_admin_bff_request(\n    p_action, p_timestamp, p_nonce, p_idempotency_key, p_payload_text, p_signature\n  ) then\n    raise exception using errcode=''28000'', message=''K2_ADMIN_REQUEST_REPLAYED'';\n  end if;\n\n  v_payload := p_payload_text::jsonb;\n  if jsonb_typeof(v_payload) <> ''object'' then\n    raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n  end if;\n  if p_action=''payment_status'' and v_payload->>''toStatus'' in (''verified'',''failed'',''refunded'') and not coalesce(public.is_admin(),false) then\n    raise exception using errcode=''42501'',message=''K2_PAYMENT_VERDICT_ADMIN_REQUIRED'';\n  end if;\n  v_payload_hash := encode(extensions.digest(convert_to(p_payload_text, ''UTF8''), ''sha256''), ''hex'');\n\n  select * into v_existing from k2_private.admin_command_receipts\n  where actor_id = v_actor and action = p_action and idempotency_key = p_idempotency_key;\n  if found then\n    if v_existing.payload_hash <> v_payload_hash then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_IDEMPOTENCY_CONFLICT'';\n    end if;\n    if v_existing.result is null then\n      raise exception using errcode=''55000'', message=''K2_ADMIN_COMMAND_IN_PROGRESS'';\n    end if;\n    return v_existing.result;\n  end if;\n\n  v_limit := case when p_action = ''packing_scan'' then 240 else 30 end;\n  select count(*)::integer into v_count from k2_private.admin_command_receipts\n  where actor_id = v_actor and action = p_action and created_at > now() - interval ''1 minute'';\n  if v_count >= v_limit then\n    raise exception using errcode=''54000'', message=''K2_ADMIN_RATE_LIMITED'';\n  end if;\n\n  insert into k2_private.admin_command_receipts(actor_id, action, idempotency_key, payload_hash)\n  values (v_actor, p_action, p_idempotency_key, v_payload_hash)\n  on conflict do nothing;\n  get diagnostics v_inserted = row_count;\n  if v_inserted = 0 then\n    select * into v_existing from k2_private.admin_command_receipts\n    where actor_id = v_actor and action = p_action and idempotency_key = p_idempotency_key;\n    if v_existing.payload_hash <> v_payload_hash then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_IDEMPOTENCY_CONFLICT'';\n    end if;\n    return v_existing.result;\n  end if;\n\n  -- Saved signed receipts above retain their historical outcome.\n  perform k2_private.lock_category_policy_v1(false);\n  if p_action = ''confirm_order'' then\n    if (v_payload - array[''orderRequestId'',''reason'']) <> ''{}''::jsonb\n       or length(trim(coalesce(v_payload->>''reason'',''''))) not between 1 and 500 then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n    end if;\n    select * into v_order from public.confirm_order_request(\n      (v_payload->>''orderRequestId'')::uuid, v_payload->>''reason''\n    );\n    v_result := jsonb_build_object(''orderId'',v_order.id,''publicReference'',v_order.public_reference,''status'',v_order.status);\n  elsif p_action = ''packing_scan'' then\n    if (v_payload - array[''orderRequestId'',''scannedCode'',''reservationId'',''lotConfirmed'']) <> ''{}''::jsonb\n       or length(trim(coalesce(v_payload->>''scannedCode'',''''))) not between 1 and 120 then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n    end if;\n    select public.record_packing_scan_exact_v1(\n      (v_payload->>''orderRequestId'')::uuid, v_payload->>''scannedCode'',\n      (v_payload->>''reservationId'')::uuid, (v_payload->>''lotConfirmed'')::boolean\n    ) into v_result;\n  elsif p_action = ''payment_status'' then\n    if (v_payload - array[''orderRequestId'',''toStatus'',''evidenceNote'',''expectedPaymentStatus'',''expectedUpdatedAt'',''paymentMethod'',''paymentAmount'',''paymentCurrency'',''payerName'',''paymentReference'',''proofAssetRef'']) <> ''{}''::jsonb\n       or coalesce(v_payload->>''toStatus'','''') not in (''awaiting_instructions'',''evidence_submitted'',''verified'',''failed'',''refunded'') then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n    end if;\n    select * into v_order from public.order_requests\n      where id=(v_payload->>''orderRequestId'')::uuid for update;\n    if not found or nullif(v_payload->>''expectedUpdatedAt'','''') is null\n       or nullif(v_payload->>''expectedPaymentStatus'','''') is null\n       or v_order.payment_status is distinct from v_payload->>''expectedPaymentStatus''\n       or v_order.updated_at is distinct from (v_payload->>''expectedUpdatedAt'')::timestamptz then\n      raise exception using errcode=''40001'', message=''K2_PAYMENT_VERSION_CONFLICT'';\n    end if;\n    select * into v_order from public.set_order_request_payment_status(\n      (v_payload->>''orderRequestId'')::uuid,\n      v_payload->>''toStatus'',\n      nullif(v_payload->>''evidenceNote'',''''),\n      case when v_payload ? ''paymentMethod'' then\n        jsonb_build_object(\n          ''method'', v_payload->>''paymentMethod'',\n          ''amount'', v_payload->>''paymentAmount'',\n          ''currency'', coalesce(v_payload->>''paymentCurrency'', ''PHP''),\n          ''payer_name'', v_payload->>''payerName'',\n          ''payment_reference'', v_payload->>''paymentReference'',\n          ''proof_asset_ref'', v_payload->>''proofAssetRef''\n        )\n      else ''{}''::jsonb end\n    );\n    v_result := jsonb_build_object(''orderId'',v_order.id,''publicReference'',v_order.public_reference,''paymentStatus'',v_order.payment_status);\n  elsif p_action = ''delivery_details'' then\n    if (v_payload - array[''orderRequestId'',''shippingAmount'',''courierName'',''trackingNumber'',''waybillUrl'',''customerConfirmed'',''note'']) <> ''{}''::jsonb\n       or length(trim(coalesce(v_payload->>''courierName'',''''))) not between 1 and 120\n       or length(trim(coalesce(v_payload->>''note'',''''))) not between 1 and 1000 then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n    end if;\n    select * into v_order from public.set_order_delivery_details(\n      (v_payload->>''orderRequestId'')::uuid, (v_payload->>''shippingAmount'')::numeric,\n      v_payload->>''courierName'', nullif(v_payload->>''trackingNumber'',''''),\n      nullif(v_payload->>''waybillUrl'',''''), (v_payload->>''customerConfirmed'')::boolean,\n      v_payload->>''note''\n    );\n    v_result := jsonb_build_object(''orderId'',v_order.id,''publicReference'',v_order.public_reference,''deliveryStatus'',v_order.delivery_status,''shippingQuoteStatus'',v_order.shipping_quote_status);\n  elsif p_action = ''fulfill_order'' then\n    if (v_payload - array[''orderRequestId'',''handoverNote'']) <> ''{}''::jsonb\n       or length(trim(coalesce(v_payload->>''handoverNote'',''''))) not between 1 and 1000 then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n    end if;\n    select * into v_order from public.fulfill_order_request(\n      (v_payload->>''orderRequestId'')::uuid, v_payload->>''handoverNote''\n    );\n    v_result := jsonb_build_object(''orderId'',v_order.id,''publicReference'',v_order.public_reference,''status'',v_order.status,''deliveryStatus'',v_order.delivery_status);\n  elsif p_action = ''transfer_lot'' then\n    if (v_payload - array[''batchId'',''quantity'',''toCustodian'',''toLocation'',''reason'']) <> ''{}''::jsonb\n       or (v_payload->>''quantity'')::integer < 1\n       or length(trim(coalesce(v_payload->>''toCustodian'',''''))) not between 1 and 140\n       or length(trim(coalesce(v_payload->>''reason'',''''))) not between 1 and 500 then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n    end if;\n    select public.transfer_inventory_custody_exact(\n      (v_payload->>''batchId'')::uuid, (v_payload->>''quantity'')::integer,\n      v_payload->>''toCustodian'', nullif(v_payload->>''toLocation'',''''), v_payload->>''reason''\n    ) into v_uuid;\n    v_result := jsonb_build_object(''destinationBatchId'',v_uuid);\n  elsif p_action = ''assign_box'' then\n    if (v_payload - array[''boxCode'',''toCustodian'',''reason'']) <> ''{}''::jsonb\n       or length(trim(coalesce(v_payload->>''boxCode'',''''))) not between 1 and 140\n       or length(trim(coalesce(v_payload->>''toCustodian'',''''))) not between 1 and 140\n       or length(trim(coalesce(v_payload->>''reason'',''''))) not between 1 and 500 then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n    end if;\n    select public.transfer_inventory_custody(\n      v_payload->>''toCustodian'', v_payload->>''boxCode'', null, v_payload->>''reason''\n    ) into v_count;\n    v_result := jsonb_build_object(''updatedLots'',v_count);\n  else\n    raise exception using errcode=''22023'', message=''K2_ADMIN_ACTION_INVALID'';\n  end if;\n\n  update k2_private.admin_command_receipts\n  set result = v_result, completed_at = now()\n  where actor_id = v_actor and action = p_action and idempotency_key = p_idempotency_key;\n  return v_result;\nend;\n","acl":["postgres=X/postgres","authenticated=X/postgres"],"config":["search_path=\"\""],"definer":true}]'::jsonb)
  as x(identity text,before text,after text,body text,acl text[],config text[],definer boolean) loop
  select * into b from pg_proc where oid=to_regprocedure(t.identity);
  if not found or pg_get_userbyid(b.proowner)<>'postgres' or b.proacl::text[] is distinct from t.acl
   or b.proconfig is distinct from t.config or b.prosecdef is distinct from t.definer then raise exception 'K2_PAYMENT_VERDICT_AUTHORITY_DRIFT';end if;
  v_hash:=encode(extensions.digest(convert_to(replace(b.prosrc,chr(13)||chr(10),chr(10)),'UTF8'),'sha256'),'hex');
  v_before:=v_before and v_hash=t.before;v_after:=v_after and v_hash=t.after;
 end loop;
 if not v_before and not v_after then raise exception 'K2_PAYMENT_VERDICT_BODY_DRIFT';end if;
 if v_after then return;end if;
 for t in select * from jsonb_to_recordset('[{"identity":"public.set_order_request_payment_status(uuid, text, text, jsonb)","before":"3c8e54cf176cd12427a3934a8bc489b98e97a43e95b4eab31698b1ee3addfdcd","after":"dbbcfc51ed09c8ce496b5de6af0dc469527b088b5f04e122e9973122ff4f1e53","body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_from text;\n  v_submitter uuid;\n  v_structured_evidence jsonb := ''{}''::jsonb;\n  v_method text;\n  v_amount numeric;\n  v_currency text;\n  v_payer_name text;\n  v_payment_reference text;\n  v_proof_asset_ref text;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() or auth.uid() is null\n     or coalesce(auth.jwt()->>''aal'','''') <> ''aal2'' then\n    raise exception using errcode=''42501'', message=''K2_ADMIN_AAL2_REQUIRED'';\n  end if;\n\n  if p_to_status in (''verified'',''failed'',''refunded'') and not coalesce(public.is_admin(),false) then\n    raise exception using errcode=''42501'',message=''K2_PAYMENT_VERDICT_ADMIN_REQUIRED'';\n  end if;\n  select * into v_order from public.order_requests where id=p_order_request_id for update;\n  if not found then raise exception using errcode=''23514'', message=''K2_PAYMENT_ORDER_INELIGIBLE''; end if;\n  v_from := v_order.payment_status;\n  if p_to_status = v_from then return v_order; end if;\n\n  if not coalesce((\n    (v_from=''not_requested'' and p_to_status=''awaiting_instructions'') or\n    (v_from=''awaiting_instructions'' and p_to_status in (''evidence_submitted'',''failed'')) or\n    (v_from=''evidence_submitted'' and p_to_status in (''verified'',''failed'')) or\n    (v_from=''failed'' and p_to_status=''evidence_submitted'') or\n    (v_from=''verified'' and p_to_status=''refunded'')\n  ), false) then\n    raise exception using errcode=''23514'', message=''K2_PAYMENT_TRANSITION_INVALID'';\n  end if;\n\n  if length(trim(coalesce(p_evidence_note,''''))) > 1000 or\n     (p_to_status not in (''awaiting_instructions'', ''evidence_submitted'') and nullif(trim(coalesce(p_evidence_note,'''')),'''') is null) then\n    raise exception using errcode=''23514'', message=''K2_PAYMENT_EVIDENCE_REQUIRED'';\n  end if;\n\n  -- Refund reconciliation remains available for a verified cancelled/fulfilled order;\n  -- all new attempts and collection/verification require an open order.\n  if p_to_status <> ''refunded'' and v_order.status not in (''submitted'',''confirmed'') then\n    raise exception using errcode=''23514'', message=''K2_PAYMENT_ORDER_INELIGIBLE'';\n  end if;\n\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  if p_to_status in (''evidence_submitted'',''verified'') then\n    -- K2_PAYMENT_BALANCE_INTEGRITY_V1\n    perform 1 from public.order_request_items where order_request_id=v_order.id order by id for update;\n    perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN''\n      and b.sku in (select sku from public.order_request_items where order_request_id=v_order.id)\n      order by b.sku for update;\n    perform 1 from public.inventory_reservations where order_request_id=v_order.id order by sku,batch_id,id for update;\n    perform 1 from public.product_batches b where b.id in (\n      select batch_id from public.inventory_reservations where order_request_id=v_order.id and status=''active''\n    ) order by b.sku,b.id for update;\n\n    if exists (\n      select 1 from public.order_request_items i\n      left join public.inventory_balances b on b.sku=i.sku and b.location_code=''MANILA_MAIN''\n      where i.order_request_id=v_order.id and (\n        b.sku is null or b.reserved is null or b.on_hand is null\n        or b.reserved<0 or b.reserved>b.on_hand\n        or b.reserved<(select coalesce(sum(r.quantity),0) from public.inventory_reservations r\n          where r.order_request_id=v_order.id and r.sku=i.sku and r.status=''active'')\n      )\n    ) then\n      raise exception using errcode=''23514'', message=''K2_PAYMENT_STOCK_INELIGIBLE'';\n    end if;\n\n    if not exists(select 1 from public.order_request_items where order_request_id=v_order.id)\n      or exists (\n        select 1 from public.inventory_reservations r\n        left join public.order_request_items i on i.id=r.order_request_item_id and i.order_request_id=v_order.id and i.sku=r.sku\n        left join public.product_batches b on b.id=r.batch_id and b.sku=r.sku\n        where r.order_request_id=v_order.id and r.status=''active''\n          and (i.id is null or b.id is null or r.quantity<=0\n            or ((r.committed_at is not null or r.committed_by is not null or r.commit_cause is not null)\n              and not coalesce(r.committed_at is not null and r.committed_by is not null\n                and r.commit_cause in (''confirmation'',''payment_verification''),false))\n            or (r.committed_at is null and (r.expires_at is null or r.expires_at<=v_k2_instant))\n            or b.reserved_quantity < (select sum(r2.quantity) from public.inventory_reservations r2 where r2.batch_id=b.id and r2.status=''active''))\n      )\n      or exists (\n        select 1 from public.order_request_items i where i.order_request_id=v_order.id\n        and i.quantity <> coalesce((\n          select sum(r.quantity) from public.inventory_reservations r\n          join public.product_batches b on b.id=r.batch_id and b.sku=r.sku\n          where r.order_request_id=v_order.id and r.order_request_item_id=i.id and r.sku=i.sku\n            and r.status=''active'' and r.quantity>0\n            and (r.committed_at is not null or r.expires_at>v_k2_instant)\n            and b.inventory_status=''available''\n            and b.quantity>=b.reserved_quantity and b.reserved_quantity>=r.quantity\n            and k2_private.lot_is_eligible_v1(b)\n        ),0)\n      ) then\n      raise exception using errcode=''23514'', message=''K2_PAYMENT_STOCK_INELIGIBLE'';\n    end if;\n  end if;\n\n  if p_to_status = ''evidence_submitted'' then\n    if p_payment_evidence is not null and p_payment_evidence <> ''{}''::jsonb then\n      v_method := p_payment_evidence->>''method'';\n      if v_method is null or v_method not in (''gcash'', ''bank_transfer'', ''maya'', ''cash'', ''other'') then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_METHOD_INVALID'';\n      end if;\n\n      begin\n        v_amount := (p_payment_evidence->>''amount'')::numeric;\n      exception when others then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_AMOUNT_INVALID'';\n      end;\n      if v_amount is null or v_amount <= 0 or v_amount > 10000000 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_AMOUNT_INVALID'';\n      end if;\n\n      v_currency := coalesce(p_payment_evidence->>''currency'', ''PHP'');\n      if v_currency <> ''PHP'' then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_CURRENCY_INVALID'';\n      end if;\n\n      v_payer_name := trim(coalesce(p_payment_evidence->>''payer_name'', ''''));\n      if length(v_payer_name) not between 1 and 140 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_PAYER_INVALID'';\n      end if;\n\n      v_payment_reference := trim(coalesce(p_payment_evidence->>''payment_reference'', ''''));\n      if length(v_payment_reference) not between 1 and 100 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_REFERENCE_INVALID'';\n      end if;\n\n      v_proof_asset_ref := trim(coalesce(p_payment_evidence->>''proof_asset_ref'', ''''));\n      if length(v_proof_asset_ref) > 500 then\n        raise exception using errcode=''22023'', message=''K2_PAYMENT_PROOF_INVALID'';\n      end if;\n\n      v_structured_evidence := jsonb_build_object(\n        ''method'', v_method,\n        ''amount'', v_amount,\n        ''currency'', v_currency,\n        ''payer_name'', v_payer_name,\n        ''payment_reference'', v_payment_reference,\n        ''proof_asset_ref'', nullif(v_proof_asset_ref, ''''),\n        ''submitted_at'', v_k2_instant,\n        ''submitted_by'', auth.uid()\n      );\n    else\n      -- If structured fields omitted, note must be present\n      if nullif(trim(coalesce(p_evidence_note, '''')), '''') is null then\n        raise exception using errcode=''23514'', message=''K2_PAYMENT_EVIDENCE_REQUIRED'';\n      end if;\n      v_structured_evidence := jsonb_build_object(\n        ''legacy_note'', trim(p_evidence_note),\n        ''submitted_at'', v_k2_instant,\n        ''submitted_by'', auth.uid()\n      );\n    end if;\n\n    update public.order_requests\n    set payment_status = p_to_status,\n        payment_evidence = v_structured_evidence,\n        updated_at = v_k2_instant\n    where id = v_order.id\n    returning * into v_order;\n\n    insert into public.order_request_events(\n      order_request_id, from_status, to_status, reason, actor_id, metadata, created_at\n    )\n    values(\n      v_order.id, v_order.status, v_order.status, trim(coalesce(p_evidence_note, v_payment_reference, '''')),\n      auth.uid(),\n      jsonb_build_object(\n        ''event'', ''payment_status_changed'',\n        ''from'', v_from,\n        ''to'', p_to_status,\n        ''corrected_attempt'', v_from = ''failed'',\n        ''payment_evidence'', v_structured_evidence\n      ),\n      v_k2_instant\n    );\n\n  elsif p_to_status = ''verified'' then\n    select actor_id into v_submitter from public.order_request_events\n      where order_request_id = v_order.id and metadata->>''event'' = ''payment_status_changed''\n        and metadata->>''to'' = ''evidence_submitted''\n      order by created_at desc, id desc limit 1;\n\n    if v_submitter is null or v_submitter = auth.uid() then\n      raise exception using errcode=''42501'', message=''K2_PAYMENT_INDEPENDENT_REVIEW_REQUIRED'';\n    end if;\n\n    -- K2_STRUCTURED_PAYMENT_STOCK_COMMITMENT_V1: after eligibility and distinct review.\n    perform public.commit_order_request_stock_v1(v_order.id,''payment_verification'',p_evidence_note);\n    v_structured_evidence := coalesce(v_order.payment_evidence, ''{}''::jsonb) || jsonb_build_object(\n      ''verified_at'', v_k2_instant,\n      ''verified_by'', auth.uid(),\n      ''verification_note'', trim(p_evidence_note)\n    );\n\n    update public.order_requests\n    set payment_status = p_to_status,\n        payment_evidence = v_structured_evidence,\n        updated_at = v_k2_instant\n    where id = v_order.id\n    returning * into v_order;\n\n    insert into public.order_request_events(\n      order_request_id, from_status, to_status, reason, actor_id, metadata, created_at\n    )\n    values(\n      v_order.id, v_order.status, v_order.status, trim(p_evidence_note),\n      auth.uid(),\n      jsonb_build_object(\n        ''event'', ''payment_status_changed'',\n        ''from'', v_from,\n        ''to'', p_to_status,\n        ''corrected_attempt'', false,\n        ''verification'', jsonb_build_object(\n          ''verified_by'', auth.uid(),\n          ''verified_at'', v_k2_instant,\n          ''note'', trim(p_evidence_note)\n        )\n      ),\n      v_k2_instant\n    );\n\n  else\n    update public.order_requests\n    set payment_status = p_to_status,\n        updated_at = v_k2_instant\n    where id = v_order.id\n    returning * into v_order;\n\n    insert into public.order_request_events(\n      order_request_id, from_status, to_status, reason, actor_id, metadata, created_at\n    )\n    values(\n      v_order.id, v_order.status, v_order.status, trim(coalesce(p_evidence_note, '''')),\n      auth.uid(),\n      jsonb_build_object(\n        ''event'', ''payment_status_changed'',\n        ''from'', v_from,\n        ''to'', p_to_status,\n        ''corrected_attempt'', v_from = ''failed''\n      ),\n      v_k2_instant\n    );\n  end if;\n\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return v_order;\nend;\n","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"definer":true},{"identity":"public.execute_admin_fulfillment_command_v1(text, bigint, uuid, uuid, text, text)","before":"8653f7f59923f7469f2bb7e77cc5dd13b5535fb3e504023994cd4f8af8199606","after":"1bcff4e4a81b21e0b9768ca0d02e9e43e3d4546d2811f41f30d2935bbff523e3","body":"\ndeclare\n  v_actor uuid := auth.uid();\n  v_payload jsonb;\n  v_payload_hash text;\n  v_existing k2_private.admin_command_receipts;\n  v_order public.order_requests;\n  v_result jsonb;\n  v_uuid uuid;\n  v_count integer;\n  v_inserted integer;\n  v_limit integer;\nbegin\n  if not k2_private.verify_admin_bff_request(\n    p_action, p_timestamp, p_nonce, p_idempotency_key, p_payload_text, p_signature\n  ) then\n    raise exception using errcode=''28000'', message=''K2_ADMIN_REQUEST_REPLAYED'';\n  end if;\n\n  v_payload := p_payload_text::jsonb;\n  if jsonb_typeof(v_payload) <> ''object'' then\n    raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n  end if;\n  if p_action=''payment_status'' and v_payload->>''toStatus'' in (''verified'',''failed'',''refunded'') and not coalesce(public.is_admin(),false) then\n    raise exception using errcode=''42501'',message=''K2_PAYMENT_VERDICT_ADMIN_REQUIRED'';\n  end if;\n  v_payload_hash := encode(extensions.digest(convert_to(p_payload_text, ''UTF8''), ''sha256''), ''hex'');\n\n  select * into v_existing from k2_private.admin_command_receipts\n  where actor_id = v_actor and action = p_action and idempotency_key = p_idempotency_key;\n  if found then\n    if v_existing.payload_hash <> v_payload_hash then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_IDEMPOTENCY_CONFLICT'';\n    end if;\n    if v_existing.result is null then\n      raise exception using errcode=''55000'', message=''K2_ADMIN_COMMAND_IN_PROGRESS'';\n    end if;\n    return v_existing.result;\n  end if;\n\n  v_limit := case when p_action = ''packing_scan'' then 240 else 30 end;\n  select count(*)::integer into v_count from k2_private.admin_command_receipts\n  where actor_id = v_actor and action = p_action and created_at > now() - interval ''1 minute'';\n  if v_count >= v_limit then\n    raise exception using errcode=''54000'', message=''K2_ADMIN_RATE_LIMITED'';\n  end if;\n\n  insert into k2_private.admin_command_receipts(actor_id, action, idempotency_key, payload_hash)\n  values (v_actor, p_action, p_idempotency_key, v_payload_hash)\n  on conflict do nothing;\n  get diagnostics v_inserted = row_count;\n  if v_inserted = 0 then\n    select * into v_existing from k2_private.admin_command_receipts\n    where actor_id = v_actor and action = p_action and idempotency_key = p_idempotency_key;\n    if v_existing.payload_hash <> v_payload_hash then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_IDEMPOTENCY_CONFLICT'';\n    end if;\n    return v_existing.result;\n  end if;\n\n  -- Saved signed receipts above retain their historical outcome.\n  perform k2_private.lock_category_policy_v1(false);\n  if p_action = ''confirm_order'' then\n    if (v_payload - array[''orderRequestId'',''reason'']) <> ''{}''::jsonb\n       or length(trim(coalesce(v_payload->>''reason'',''''))) not between 1 and 500 then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n    end if;\n    select * into v_order from public.confirm_order_request(\n      (v_payload->>''orderRequestId'')::uuid, v_payload->>''reason''\n    );\n    v_result := jsonb_build_object(''orderId'',v_order.id,''publicReference'',v_order.public_reference,''status'',v_order.status);\n  elsif p_action = ''packing_scan'' then\n    if (v_payload - array[''orderRequestId'',''scannedCode'',''reservationId'',''lotConfirmed'']) <> ''{}''::jsonb\n       or length(trim(coalesce(v_payload->>''scannedCode'',''''))) not between 1 and 120 then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n    end if;\n    select public.record_packing_scan_exact_v1(\n      (v_payload->>''orderRequestId'')::uuid, v_payload->>''scannedCode'',\n      (v_payload->>''reservationId'')::uuid, (v_payload->>''lotConfirmed'')::boolean\n    ) into v_result;\n  elsif p_action = ''payment_status'' then\n    if (v_payload - array[''orderRequestId'',''toStatus'',''evidenceNote'',''expectedPaymentStatus'',''expectedUpdatedAt'',''paymentMethod'',''paymentAmount'',''paymentCurrency'',''payerName'',''paymentReference'',''proofAssetRef'']) <> ''{}''::jsonb\n       or coalesce(v_payload->>''toStatus'','''') not in (''awaiting_instructions'',''evidence_submitted'',''verified'',''failed'',''refunded'') then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n    end if;\n    select * into v_order from public.order_requests\n      where id=(v_payload->>''orderRequestId'')::uuid for update;\n    if not found or nullif(v_payload->>''expectedUpdatedAt'','''') is null\n       or nullif(v_payload->>''expectedPaymentStatus'','''') is null\n       or v_order.payment_status is distinct from v_payload->>''expectedPaymentStatus''\n       or v_order.updated_at is distinct from (v_payload->>''expectedUpdatedAt'')::timestamptz then\n      raise exception using errcode=''40001'', message=''K2_PAYMENT_VERSION_CONFLICT'';\n    end if;\n    select * into v_order from public.set_order_request_payment_status(\n      (v_payload->>''orderRequestId'')::uuid,\n      v_payload->>''toStatus'',\n      nullif(v_payload->>''evidenceNote'',''''),\n      case when v_payload ? ''paymentMethod'' then\n        jsonb_build_object(\n          ''method'', v_payload->>''paymentMethod'',\n          ''amount'', v_payload->>''paymentAmount'',\n          ''currency'', coalesce(v_payload->>''paymentCurrency'', ''PHP''),\n          ''payer_name'', v_payload->>''payerName'',\n          ''payment_reference'', v_payload->>''paymentReference'',\n          ''proof_asset_ref'', v_payload->>''proofAssetRef''\n        )\n      else ''{}''::jsonb end\n    );\n    v_result := jsonb_build_object(''orderId'',v_order.id,''publicReference'',v_order.public_reference,''paymentStatus'',v_order.payment_status);\n  elsif p_action = ''delivery_details'' then\n    if (v_payload - array[''orderRequestId'',''shippingAmount'',''courierName'',''trackingNumber'',''waybillUrl'',''customerConfirmed'',''note'']) <> ''{}''::jsonb\n       or length(trim(coalesce(v_payload->>''courierName'',''''))) not between 1 and 120\n       or length(trim(coalesce(v_payload->>''note'',''''))) not between 1 and 1000 then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n    end if;\n    select * into v_order from public.set_order_delivery_details(\n      (v_payload->>''orderRequestId'')::uuid, (v_payload->>''shippingAmount'')::numeric,\n      v_payload->>''courierName'', nullif(v_payload->>''trackingNumber'',''''),\n      nullif(v_payload->>''waybillUrl'',''''), (v_payload->>''customerConfirmed'')::boolean,\n      v_payload->>''note''\n    );\n    v_result := jsonb_build_object(''orderId'',v_order.id,''publicReference'',v_order.public_reference,''deliveryStatus'',v_order.delivery_status,''shippingQuoteStatus'',v_order.shipping_quote_status);\n  elsif p_action = ''fulfill_order'' then\n    if (v_payload - array[''orderRequestId'',''handoverNote'']) <> ''{}''::jsonb\n       or length(trim(coalesce(v_payload->>''handoverNote'',''''))) not between 1 and 1000 then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n    end if;\n    select * into v_order from public.fulfill_order_request(\n      (v_payload->>''orderRequestId'')::uuid, v_payload->>''handoverNote''\n    );\n    v_result := jsonb_build_object(''orderId'',v_order.id,''publicReference'',v_order.public_reference,''status'',v_order.status,''deliveryStatus'',v_order.delivery_status);\n  elsif p_action = ''transfer_lot'' then\n    if (v_payload - array[''batchId'',''quantity'',''toCustodian'',''toLocation'',''reason'']) <> ''{}''::jsonb\n       or (v_payload->>''quantity'')::integer < 1\n       or length(trim(coalesce(v_payload->>''toCustodian'',''''))) not between 1 and 140\n       or length(trim(coalesce(v_payload->>''reason'',''''))) not between 1 and 500 then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n    end if;\n    select public.transfer_inventory_custody_exact(\n      (v_payload->>''batchId'')::uuid, (v_payload->>''quantity'')::integer,\n      v_payload->>''toCustodian'', nullif(v_payload->>''toLocation'',''''), v_payload->>''reason''\n    ) into v_uuid;\n    v_result := jsonb_build_object(''destinationBatchId'',v_uuid);\n  elsif p_action = ''assign_box'' then\n    if (v_payload - array[''boxCode'',''toCustodian'',''reason'']) <> ''{}''::jsonb\n       or length(trim(coalesce(v_payload->>''boxCode'',''''))) not between 1 and 140\n       or length(trim(coalesce(v_payload->>''toCustodian'',''''))) not between 1 and 140\n       or length(trim(coalesce(v_payload->>''reason'',''''))) not between 1 and 500 then\n      raise exception using errcode=''22023'', message=''K2_ADMIN_PAYLOAD_INVALID'';\n    end if;\n    select public.transfer_inventory_custody(\n      v_payload->>''toCustodian'', v_payload->>''boxCode'', null, v_payload->>''reason''\n    ) into v_count;\n    v_result := jsonb_build_object(''updatedLots'',v_count);\n  else\n    raise exception using errcode=''22023'', message=''K2_ADMIN_ACTION_INVALID'';\n  end if;\n\n  update k2_private.admin_command_receipts\n  set result = v_result, completed_at = now()\n  where actor_id = v_actor and action = p_action and idempotency_key = p_idempotency_key;\n  return v_result;\nend;\n","acl":["postgres=X/postgres","authenticated=X/postgres"],"config":["search_path=\"\""],"definer":true}]'::jsonb)
  as x(identity text,before text,after text,body text,acl text[],config text[],definer boolean) loop
  select p.*,pg_get_functiondef(p.oid) definition into b from pg_proc p where oid=to_regprocedure(t.identity);
  execute replace(b.definition,b.prosrc,t.body);select * into a from pg_proc where oid=b.oid;
  if a.prosrc is distinct from t.body or (to_jsonb(a)-'prosrc') is distinct from (to_jsonb(b)-'prosrc'-'definition') then raise exception 'K2_PAYMENT_VERDICT_METADATA_CHANGED';end if;
 end loop;
end $financial_authority$;
commit;
